package com.ecommerce.product; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="categories") public class Category { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false,unique=true) String name; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="parent_id") Category parent; @Column(name="created_at",nullable=false,updatable=false) Instant createdAt; @PrePersist void c(){createdAt=Instant.now();} public UUID getId(){return id;} public String getName(){return name;} public Category getParent(){return parent;} public void setName(String v){name=v;} public void setParent(Category v){parent=v;} }
